1	// csrc/fused/sm_90/mega_vit_real_adamw_tc.cu — R2 TENSOR-CORE ViT cell driver
2	// TU (DESIGN-TC-PIPELINE.md Fork B, the ViT twin of mega_decoder_real_adamw_tc
3	// .cu). The bf16 wgmma fwd+bwd+AdamW persistent megakernel, compiled with
4	// -DSG_TUNED_GEMM_IMPL=1 so the wgmma branch of fused_vit_megakernel.cuh is
5	// selected (the scalar default TU mega_vit_real_adamw.cu is UNTOUCHED and ships
6	// as the live path).
7	//
8	// BUILD-ONLY extension of the build path: this is a SECOND compiled TU for the
9	// SAME (vit × adamw) cell, selected by the GEMM impl token. It is NOT wired into
10	// compile.py / dispatch — the parity gate (tests/hw/test_vit_tc.py PART 2)
11	// JIT-loads it via cpp_extension.load and drives it directly through the pybind
12	// entries below. It owns its OWN PYBIND11_MODULE(TORCH_EXTENSION_NAME, …), so
13	// setup.py's CONTENT filter (_owns_extension_module) AUTO-EXCLUDES it from the
14	// shipped _ops glob (no setup.py change needed — exactly the decoder TC TU
15	// pattern).
16	//
17	// HONESTY: this exercises the REAL tensor-core path (HGMMA in SASS). No scalar
18	// fallback, no surrogate.
19	
20	#define SG_TUNED_GEMM_IMPL 1   // select the wgmma cell driver
21	
22	#include <torch/extension.h>
23	#include <c10/cuda/CUDAStream.h>
24	#include <c10/cuda/CUDAException.h>
25	#include <cuda_runtime.h>
26	#include <cuda_bf16.h>
27	#include <cstdint>
28	
29	#include "csrc/fused/sm_90/fused_vit_megakernel.cuh"
30	
31	namespace vit = ::sg::fused::sm90::vit;
32	namespace vittc = ::sg::fused::sm90::vittc;
33	namespace wgs = ::sg::sm90::wgs;
34	using ::sg::fused::PersistentContext;
35	using ::sg::fused::sm90::ViTInputCtx;
36	using ::sg::fused::sm90::FusedOptState;
37	using ::sg::fused::sm90::OptId;
38	using ::sg::fused::sm90::kVitTotalElems;
39	using ::sg::fused::sm90::kVitNumTensors;
40	
41	// ════════════════════════════════════════════════════════════════════════════
42	//  PART 1 — GEMM-orientation micro-gates (the SAME engine the decoder selftest
43	//  silicon-gated 13/13; the engine is model-agnostic, but exercising it through
44	//  a ViT TU at the ViT TILE_M=1088 (17 stacked m64 atoms) is the honest witness
45	//  for the ViT path's M-atom stacking). Three orientations: fwd / dX / dW, each
46	//  one tiny GEMM on a single CTA (256 thr) returning the fp32 result. ──────────
47	// ════════════════════════════════════════════════════════════════════════════
48	
49	static size_t arena_bytes() { return (size_t)(64 * 16 + 128 * 16) * sizeof(__nv_bfloat16) + 256; }
50	
51	// (fwd) Y[M,Nout] = X[M,Kin] @ W[Nout,Kin]^T. M = TILE_M (17 atoms). N-tiled.
52	template <int N>
53	__global__ void __launch_bounds__(256)
54	gemm_fwd_kernel(const __nv_bfloat16* __restrict__ X, const __nv_bfloat16* __restrict__ W,
55	                float* __restrict__ D, int Kin, int Nout) {
56	#if defined(__CUDA_ARCH__) && (__CUDA_ARCH__ >= 900)
57	    extern __shared__ __nv_bfloat16 smem[];
58	    __nv_bfloat16* sA = smem; __nv_bfloat16* sB = sA + 64 * 16;
59	    const int M = vittc::kTileM, m_atoms = M / 64, k_steps = Kin / 16;
60	    for (int n0 = 0; n0 < Nout; n0 += N) {
61	        const int n_real = (Nout - n0) < N ? (Nout - n0) : N;
62	        auto srcA = [&] (int m, int k) -> __nv_bfloat16 { return X[(int64_t)m * Kin + k]; };
63	        auto srcB = [&] (int n, int k) -> __nv_bfloat16 {
64	            int nn = n0 + n; return nn < Nout ? W[(int64_t)nn * Kin + k] : __float2bfloat16(0.f); };
65	        auto out  = [&] (int m, int n, float v) { if (m < M) D[(int64_t)m * Nout + n0 + n] = v; };
66	        vittc::tc_gemm_block_unpipelined<N, /*MaxAtomsM=*/vittc::kAtomsM>(
67	            0, m_atoms, n_real, k_steps, srcA, srcB, out, sA, sB);
68	    }
69	#else
70	    (void)X; (void)W; (void)D; (void)Kin; (void)Nout;
71	#endif
72	}
73	
74	// (dX) dX[m,kin] = Σ_out dY[m,out]·W[out,kin]. N(wgmma)=Kin, K=Nout, W transposed.
75	template <int N>
76	__global__ void __launch_bounds__(256)
77	gemm_dx_kernel(const __nv_bfloat16* __restrict__ dY, const __nv_bfloat16* __restrict__ W,
78	               float* __restrict__ dX, int Nout) {
79	#if defined(__CUDA_ARCH__) && (__CUDA_ARCH__ >= 900)
80	    extern __shared__ __nv_bfloat16 smem[];
81	    __nv_bfloat16* sA = smem; __nv_bfloat16* sB = sA + 64 * 16;
82	    const int M = vittc::kTileM, m_atoms = M / 64, k_steps = Nout / 16;
83	    auto srcA = [&] (int m, int k) -> __nv_bfloat16 { return dY[(int64_t)m * Nout + k]; };
84	    auto srcB = [&] (int n, int k) -> __nv_bfloat16 { return W[(int64_t)k * N + n]; };
85	    auto out  = [&] (int m, int n, float v) { if (m < M) dX[(int64_t)m * N + n] = v; };
86	    vittc::tc_gemm_block_unpipelined<N, /*MaxAtomsM=*/vittc::kAtomsM>(
87	        0, m_atoms, /*n_real=*/N, k_steps, srcA, srcB, out, sA, sB);
88	#else
89	    (void)dY; (void)W; (void)dX; (void)Nout;
90	#endif
91	}
92	
93	// (dW) dW[out,in] = Σ_t dY[t,out]·X[t,in]. BOTH transposed, K=T multi-k-step.
94	template <int N>
95	__global__ void __launch_bounds__(256)
96	gemm_dw_kernel(const __nv_bfloat16* __restrict__ dY, const __nv_bfloat16* __restrict__ X,
97	               float* __restrict__ dW, int Nout, int T) {
98	#if defined(__CUDA_ARCH__) && (__CUDA_ARCH__ >= 900)
99	    extern __shared__ __nv_bfloat16 smem[];
100	    __nv_bfloat16* sA = smem; __nv_bfloat16* sB = sA + 64 * 16;
101	    const int k_steps = T / 16, m_atoms = (Nout + 63) / 64;   // up to 8 for Nout=512
102	    auto srcA = [&] (int m, int k) -> __nv_bfloat16 {
103	        return m < Nout ? dY[(int64_t)k * Nout + m] : __float2bfloat16(0.f); };
104	    auto srcB = [&] (int n, int k) -> __nv_bfloat16 { return X[(int64_t)k * N + n]; };
105	    auto out  = [&] (int m, int n, float v) { if (m < Nout) dW[(int64_t)m * N + n] = v; };
106	    vittc::tc_gemm_block_unpipelined<N, /*MaxAtomsM=*/8>(
107	        0, m_atoms, /*n_real=*/N, k_steps, srcA, srcB, out, sA, sB);
108	#else
109	    (void)dY; (void)X; (void)dW; (void)Nout; (void)T;
110	#endif
111	}
112	
113	template <int N>
114	static torch::Tensor run_fwd(torch::Tensor X, torch::Tensor W, int Kin, int Nout) {
115	    TORCH_CHECK(X.scalar_type() == torch::kBFloat16 && W.scalar_type() == torch::kBFloat16);
116	    TORCH_CHECK(X.is_cuda() && W.is_cuda() && X.is_contiguous() && W.is_contiguous());
117	    auto D = torch::zeros({vittc::kTileM, Nout}, torch::dtype(torch::kFloat32).device(X.device()));
118	    size_t smem = arena_bytes();
119	    auto stream = at::cuda::getCurrentCUDAStream();
120	    cudaFuncSetAttribute(gemm_fwd_kernel<N>, cudaFuncAttributeMaxDynamicSharedMemorySize, (int)smem);
121	    gemm_fwd_kernel<N><<<1, 256, smem, stream>>>(
122	        reinterpret_cast<const __nv_bfloat16*>(X.data_ptr()),
123	        reinterpret_cast<const __nv_bfloat16*>(W.data_ptr()), D.data_ptr<float>(), Kin, Nout);
124	    C10_CUDA_CHECK(cudaGetLastError());
125	    return D;
126	}
127	template <int N>
128	static torch::Tensor run_dx(torch::Tensor dY, torch::Tensor W, int Nout) {
129	    auto dX = torch::zeros({vittc::kTileM, N}, torch::dtype(torch::kFloat32).device(dY.device()));
130	    size_t smem = arena_bytes();
131	    auto stream = at::cuda::getCurrentCUDAStream();
132	    cudaFuncSetAttribute(gemm_dx_kernel<N>, cudaFuncAttributeMaxDynamicSharedMemorySize, (int)smem);
133	    gemm_dx_kernel<N><<<1, 256, smem, stream>>>(
134	        reinterpret_cast<const __nv_bfloat16*>(dY.data_ptr()),
135	        reinterpret_cast<const __nv_bfloat16*>(W.data_ptr()), dX.data_ptr<float>(), Nout);
136	    C10_CUDA_CHECK(cudaGetLastError());
137	    return dX;
138	}
139	template <int N>
140	static torch::Tensor run_dw(torch::Tensor dY, torch::Tensor X, int Nout, int T) {
141	    auto dW = torch::zeros({Nout, N}, torch::dtype(torch::kFloat32).device(dY.device()));
142	    size_t smem = arena_bytes();
143	    auto stream = at::cuda::getCurrentCUDAStream();
144	    cudaFuncSetAttribute(gemm_dw_kernel<N>, cudaFuncAttributeMaxDynamicSharedMemorySize, (int)smem);
145	    gemm_dw_kernel<N><<<1, 256, smem, stream>>>(
146	        reinterpret_cast<const __nv_bfloat16*>(dY.data_ptr()),
147	        reinterpret_cast<const __nv_bfloat16*>(X.data_ptr()), dW.data_ptr<float>(), Nout, T);
148	    C10_CUDA_CHECK(cudaGetLastError());
149	    return dW;
150	}
151	
152	static torch::Tensor gemm_fwd(torch::Tensor X, torch::Tensor W, int N, int Kin, int Nout) {
153	    switch (N) { case 96: return run_fwd<96>(X, W, Kin, Nout); case 128: return run_fwd<128>(X, W, Kin, Nout);
154	                 default: TORCH_CHECK(false, "fwd N ", N); }
155	}
156	static torch::Tensor gemm_dx(torch::Tensor dY, torch::Tensor W, int N, int Nout) {
157	    switch (N) { case 96: return run_dx<96>(dY, W, Nout); case 128: return run_dx<128>(dY, W, Nout);
158	                 default: TORCH_CHECK(false, "dx N ", N); }
159	}
160	static torch::Tensor gemm_dw(torch::Tensor dY, torch::Tensor X, int N, int Nout, int T) {
161	    switch (N) { case 96: return run_dw<96>(dY, X, Nout, T); case 128: return run_dw<128>(dY, X, Nout, T);
162	                 default: TORCH_CHECK(false, "dw N ", N); }
163	}
164	
165	// ════════════════════════════════════════════════════════════════════════════
166	//  PART 2 — full-cell driver. One persistent set of barrier/queue counters + the
167	//  TC workspace, cached per device. Re-created if a larger B requires a larger
168	//  workspace.
169	// ════════════════════════════════════════════════════════════════════════════
170	struct TcScratch {
171	    torch::Tensor g_next, g_arrived, g_generation, workspace;
172	    int n_ctas = 0;
173	    int64_t ws_floats = 0;
174	};
175	
176	static int tc_effective_nctas(const torch::Tensor& params, int ncta_cap) {
177	    int dev = params.get_device();
178	    int n_sms = 1;
179	    cudaDeviceGetAttribute(&n_sms, cudaDevAttrMultiProcessorCount, dev);
180	    int n = n_sms;
181	    if (ncta_cap > 0 && ncta_cap < n) n = ncta_cap;
182	    return n;
183	}
184	
185	static TcScratch& tc_scratch_for(const torch::Tensor& params, int B, int nCTA) {
186	    static TcScratch s;
187	    const int T = B * vit::kSeq;
188	    const int64_t need = ::sg::fused::sm90::vit_tc_workspace_floats(T, B, nCTA);
189	    if (!s.g_next.defined()) {
190	        auto opt_i = torch::dtype(torch::kInt32).device(params.device());
191	        s.g_next = torch::zeros({1}, opt_i);
192	        s.g_arrived = torch::zeros({1}, opt_i);
193	        s.g_generation = torch::zeros({1}, opt_i);
194	    }
195	    s.n_ctas = nCTA;
196	    if (s.ws_floats < need) {
197	        auto opt_f = torch::dtype(torch::kFloat32).device(params.device());
198	        s.workspace = torch::empty({need}, opt_f);
199	        s.ws_floats = need;
200	    }
201	    return s;
202	}
203	
204	// tc_train_step: one Fork-B TC step. params [total] fp32 (updated in place);
205	// patches [B, kNPatch, kPatch] fp32; targets [B] int32; state [3*total] fp32.
206	// Returns {loss (cpu float scalar), grad [total] fp32 (the reduced grad)}.
207	static std::vector<torch::Tensor> tc_train_step(
208	        torch::Tensor params, torch::Tensor patches, torch::Tensor targets,
209	        torch::Tensor state, double lr, double beta1, double beta2, double eps,
210	        double weight_decay, double bc1, double bc2, int64_t step,
211	        int64_t ncta_cap) {
212	    TORCH_CHECK(params.is_cuda() && params.scalar_type() == torch::kFloat32 && params.is_contiguous());
213	    TORCH_CHECK(params.numel() == kVitTotalElems, "params must be the flat ViT blob (", kVitTotalElems, ")");
214	    TORCH_CHECK(patches.is_cuda() && patches.scalar_type() == torch::kFloat32 && patches.is_contiguous());
215	    TORCH_CHECK(targets.is_cuda() && targets.scalar_type() == torch::kInt32 && targets.is_contiguous());
216	    const int B = (int)targets.numel();
217	    TORCH_CHECK(patches.numel() == (int64_t)B * vit::kNPatch * vit::kPatch,
218	                "patches must be [B, kNPatch, kPatch]");
219	    TORCH_CHECK((B % 16) == 0, "TC path requires B %% 16 == 0 (dW K-loop is 16-step atoms)");
220	    const int64_t total = kVitTotalElems;
221	    TORCH_CHECK(state.is_cuda() && state.scalar_type() == torch::kFloat32 && state.is_contiguous()
222	                && state.numel() >= 3 * total, "state must be contiguous fp32 [>=3*total]");
223	
224	    const int nCTA = tc_effective_nctas(params, (int)ncta_cap);
225	    TcScratch& sc = tc_scratch_for(params, B, nCTA);
226	    auto grad = torch::zeros({total}, torch::dtype(torch::kFloat32).device(params.device()));
227	    auto loss_dev = torch::zeros({1}, torch::dtype(torch::kFloat32).device(params.device()));
228	
229	    PersistentContext ctx{
230	        sc.g_next.data_ptr<int>(),
231	        reinterpret_cast<unsigned*>(sc.g_arrived.data_ptr<int>()),
232	        reinterpret_cast<unsigned*>(sc.g_generation.data_ptr<int>()),
233	        kVitNumTensors,
234	        0u};
235	
236	    FusedOptState st;
237	    float* m = state.data_ptr<float>();
238	    st.exp_avg = m;
239	    st.exp_avg_sq = m + total;
240	    st.lr = (float)lr; st.beta1 = (float)beta1; st.beta2 = (float)beta2;
241	    st.eps = (float)eps; st.wd = (float)weight_decay;
242	    st.bc1 = (float)bc1; st.bc2 = (float)bc2;
243	
244	    ViTInputCtx in;
245	    in.patches = patches.data_ptr<float>();
246	    in.targets = targets.data_ptr<int>();
247	    in.B = B;
248	    in.workspace = sc.workspace.data_ptr<float>();
249	    in.loss_out = loss_dev.data_ptr<float>();
250	
251	    cudaStream_t stream = c10::cuda::getCurrentCUDAStream().stream();
252	    cudaError_t err = ::sg::fused::sm90::launch_fused_vit_megakernel_tc<OptId::AdamW>(
253	        ctx, params.data_ptr<float>(), in, grad.data_ptr<float>(),
254	        (float)lr, (int)step, st, stream, nCTA);
255	    TORCH_CHECK(err == cudaSuccess, "TC megakernel launch failed: ", cudaGetErrorString(err));
256	    C10_CUDA_CHECK(cudaStreamSynchronize(stream));
257	
258	    return {loss_dev.to(torch::kCPU), grad};
259	}
260	
261	// CALIBRATION HOOK (test_vit_tc.py::test_tc_dw_gemm_exact_on_own_operands): slice
262	// the kernel's OWN stored bf16 acts dY_ff2[L1] [T,d] and X_gact[L1] [T,dff] from
263	// the workspace, returned as fp32 CPU tensors. The gate contracts them in fp32
264	// ascending-t and compares to the kernel's ff2.weight grad slice — isolating the
265	// dW GEMM (incl. the ONLY Kin=dff multi-N-tile path) from operand-chain bf16
266	// divergence. Re-uses the cached workspace from the last tc_train_step.
267	static std::vector<torch::Tensor> tc_dump_ff2_operands(torch::Tensor params, int64_t B) {
268	    TcScratch& sc = tc_scratch_for(params, (int)B, tc_effective_nctas(params, 4));
269	    const int T = (int)B * vit::kSeq;
270	    const int64_t d = vit::kD, dff = vit::kDff;
271	    const int Tp = (int)B * vit::kNPatch;
272	    auto acts_bf16 = sc.workspace.slice(0, 0, ::sg::fused::sm90::vit_tc_acts_floats(T, (int)B))
273	                         .view(torch::kBFloat16);
274	    // mirror vit_acts_bind: walk to dY_ff2[1] and X_gact[1].
275	    const int64_t Td = (int64_t)T * d, T3d = (int64_t)T * 3 * d, Tff = (int64_t)T * dff;
276	    int64_t off = (int64_t)Tp * vit::kPatch;    // skip X_patch
277	    int64_t off_Xgact1 = -1, off_dYff2_1 = -1;
278	    for (int li = 0; li < vit::kLayers; ++li) {
279	        off += Td;          // X_in
280	        off += Td;          // X_ctx
281	        off += Td;          // X_x1
282	        if (li == 1) off_Xgact1 = off;
283	        off += Tff;         // X_gact
284	        off += T3d;         // dY_qkv
285	        off += Td;          // dY_a
286	        off += Tff;         // dY_ff0
287	        if (li == 1) off_dYff2_1 = off;
288	        off += Td;          // dY_ff2
289	    }
290	    auto Xgact1 = acts_bf16.slice(0, off_Xgact1, off_Xgact1 + Tff).to(torch::kFloat32).to(torch::kCPU);
291	    auto dYff2_1 = acts_bf16.slice(0, off_dYff2_1, off_dYff2_1 + Td).to(torch::kFloat32).to(torch::kCPU);
292	    return {dYff2_1, Xgact1};  // [T*d], [T*dff]
293	}
294	
295	// scalar_train_step: the SAME (vit × AdamW) cell run through the SCALAR default
296	// launcher (launch_fused_vit_megakernel<AdamW>, which lives OUTSIDE the wgmma
297	// guard — so this wgmma-token TU can still call it). ONLY for the step-time gate
298	// (times the live scalar path and the TC path BACK-TO-BACK in one process → an
299	// honest scalar:TC ratio). NOT the shipped invocation. Returns {loss, reduced
300	// grad} like tc_train_step.
301	static std::vector<torch::Tensor> scalar_train_step(
302	        torch::Tensor params, torch::Tensor patches, torch::Tensor targets,
303	        torch::Tensor state, double lr, double beta1, double beta2, double eps,
304	        double weight_decay, double bc1, double bc2, int64_t step) {
305	    TORCH_CHECK(params.is_cuda() && params.scalar_type() == torch::kFloat32 && params.is_contiguous());
306	    TORCH_CHECK(params.numel() == kVitTotalElems, "params must be the flat ViT blob (", kVitTotalElems, ")");
307	    TORCH_CHECK(patches.is_cuda() && patches.scalar_type() == torch::kFloat32 && patches.is_contiguous());
308	    TORCH_CHECK(targets.is_cuda() && targets.scalar_type() == torch::kInt32 && targets.is_contiguous());
309	    const int B = (int)targets.numel();
310	    TORCH_CHECK(patches.numel() == (int64_t)B * vit::kNPatch * vit::kPatch, "patches must be [B, kNPatch, kPatch]");
311	    const int64_t total = kVitTotalElems;
312	    TORCH_CHECK(state.is_cuda() && state.scalar_type() == torch::kFloat32 && state.is_contiguous()
313	                && state.numel() >= 3 * total, "state must be contiguous fp32 [>=3*total]");
314	
315	    int dev = params.get_device();
316	    int n_sms = 1;
317	    cudaDeviceGetAttribute(&n_sms, cudaDevAttrMultiProcessorCount, dev);
318	
319	    static torch::Tensor s_gn, s_ga, s_gg, s_ws;
320	    static int64_t s_ws_floats = 0;
321	    const int64_t need = (int64_t)n_sms * total + n_sms + 1;
322	    if (!s_gn.defined()) {
323	        auto oi = torch::dtype(torch::kInt32).device(params.device());
324	        s_gn = torch::zeros({1}, oi); s_ga = torch::zeros({1}, oi); s_gg = torch::zeros({1}, oi);
325	    }
326	    if (s_ws_floats < need) {
327	        s_ws = torch::empty({need}, torch::dtype(torch::kFloat32).device(params.device()));
328	        s_ws_floats = need;
329	    }
330	    auto grad = torch::zeros({total}, torch::dtype(torch::kFloat32).device(params.device()));
331	    float* loss_out = s_ws.data_ptr<float>() + (int64_t)n_sms * total + n_sms;
332	
333	    PersistentContext ctx{
334	        s_gn.data_ptr<int>(),
335	        reinterpret_cast<unsigned*>(s_ga.data_ptr<int>()),
336	        reinterpret_cast<unsigned*>(s_gg.data_ptr<int>()),
337	        kVitNumTensors, 0u};
338	
339	    FusedOptState st;
340	    float* m = state.data_ptr<float>();
341	    st.exp_avg = m; st.exp_avg_sq = m + total;
342	    st.lr = (float)lr; st.beta1 = (float)beta1; st.beta2 = (float)beta2;
343	    st.eps = (float)eps; st.wd = (float)weight_decay;
344	    st.bc1 = (float)bc1; st.bc2 = (float)bc2;
345	
346	    ViTInputCtx in;
347	    in.patches = patches.data_ptr<float>();
348	    in.targets = targets.data_ptr<int>();
349	    in.B = B;
350	    in.workspace = s_ws.data_ptr<float>();
351	    in.loss_out = loss_out;
352	
353	    cudaStream_t stream = c10::cuda::getCurrentCUDAStream().stream();
354	    cudaError_t err = ::sg::fused::sm90::launch_fused_vit_megakernel<OptId::AdamW>(
355	        ctx, params.data_ptr<float>(), in, grad.data_ptr<float>(),
356	        (float)lr, (int)step, st, stream);
357	    TORCH_CHECK(err == cudaSuccess, "scalar megakernel launch failed: ", cudaGetErrorString(err));
358	    C10_CUDA_CHECK(cudaStreamSynchronize(stream));
359	
360	    auto loss_cpu = s_ws.slice(0, (int64_t)n_sms * total + n_sms, (int64_t)n_sms * total + n_sms + 1)
361	                        .to(torch::kCPU);
362	    return {loss_cpu, grad};
363	}
