31	namespace {
32	struct VitTcLauncherScratch {
33	    int*      g_next = nullptr;
34	    unsigned* g_arrived = nullptr;
35	    unsigned* g_generation = nullptr;
36	    float*    workspace = nullptr;
37	    int64_t   ws_floats = 0;
38	    int       dev = -1;
39	};
40	
41	VitTcLauncherScratch& vit_tc_launcher_scratch(int dev, int64_t need_floats) {
42	    static VitTcLauncherScratch s;
43	    if (s.dev != dev) {
44	        s.dev = dev;
45	        if (!s.g_next)       cudaMalloc(&s.g_next, sizeof(int));
46	        if (!s.g_arrived)    cudaMalloc(&s.g_arrived, sizeof(unsigned));
47	        if (!s.g_generation) cudaMalloc(&s.g_generation, sizeof(unsigned));
48	    }
49	    if (s.ws_floats < need_floats) {
50	        if (s.workspace) cudaFree(s.workspace);
51	        cudaMalloc(&s.workspace, (size_t)need_floats * sizeof(float));
52	        s.ws_floats = need_floats;
53	    }
54	    return s;
55	}
56	}  // anonymous namespace
