61	//  SG_TUNED_GEMM_IMPL — the per-cell GEMM-engine selector (mirrors the decoder
62	//  twin fused_decoder_megakernel.cuh). The scalar fp32 owner-computes path
63	//  (model_stage_vit.cuh) and the bf16 wgmma tensor-core path
64	//  (model_stage_vit_tc.cuh) are compiled ALONGSIDE each other; the autotuner
65	//  injects -DSG_TUNED_GEMM_IMPL=<token> per-TU to pick one. Absent the macro,
66	//  the SCALAR path compiles verbatim (CONTRACT rule 3) — the shipped default
67	//  that all of test_vit_megakernel.py's L3-REAL gates exercise; adding this seam
68	//  must leave those numbers BIT-IDENTICAL (the macros below are only #defined
69	//  here; the scalar kernel body does not reference them).
70	//
71	//  Tokens are integers (the preprocessor cannot compare strings):
72	//      SG_GEMM_IMPL_SCALAR = 0   (default; the verbatim fp32 path below)
73	//      SG_GEMM_IMPL_WGMMA  = 1   (the Fork-B bf16 tensor-core ViT cell)
74	//
75	//  The wgmma token pulls in the validated GEMM engine (model_stage_vit_tc.cuh)
76	//  and the phase-restructured fwd+bwd+AdamW persistent kernel at the BOTTOM of
77	//  this file (fused_vit_megakernel_tc / launch_fused_vit_megakernel_tc). The
78	//  scalar default path is UNCHANGED and its gates stay bit-identical; this is a
79	//  PARALLEL kernel, not an edit of the scalar one.
80	// ============================================================================
81	#ifndef SG_GEMM_IMPL_SCALAR
82	#define SG_GEMM_IMPL_SCALAR 0
83	#endif
84	#ifndef SG_GEMM_IMPL_WGMMA
85	#define SG_GEMM_IMPL_WGMMA  1
86	#endif
87	#ifndef SG_TUNED_GEMM_IMPL
88	#define SG_TUNED_GEMM_IMPL SG_GEMM_IMPL_SCALAR
