100	// Compile-time guard: the byte budget the launcher uses (sizeof(VitSampleSmem))
101	// MUST equal the literal the layout header documents + bounds-checks (227 KB cap).
102	static_assert(sizeof(VitSampleSmem) == (size_t)vit_layout_check::kVitSampleSmemBytes,
103	              "fused_vit_megakernel: sizeof(VitSampleSmem) != the documented "
104	              "kVitSampleSmemBytes in vit_layout.cuh — update both together.");
105	
106	// Rebase a FusedOptState's per-element state pointers to a parameter-tensor slice
107	// at `off` within the flat [m|v|extra] layout. Per-TENSOR fields and all scalars
108	// pass through unchanged. (Identical to the decoder's rebase_state; redefined here
109	// under a vit_ name so this header stays self-contained — the decoder file is
110	// owned by a sibling agent and must not be included.)
111	template <OptId Opt>
112	__device__ __forceinline__ FusedOptState
113	vit_rebase_state(const FusedOptState& s, int64_t off) {
114	    FusedOptState t = s;  // scalars + per-tensor pointers copy as-is
115	    if (t.exp_avg)    t.exp_avg    += off;
116	    if (t.exp_avg_sq) t.exp_avg_sq += off;
117	    if (t.ema)        t.ema        += off;
118	    if (t.sam_dir)    t.sam_dir    += off;
119	    if (t.s_track)    t.s_track    += off;
120	    if (t.mu)         t.mu         += off;
121	    if (t.orth)       t.orth       += off;
122	    if (t.smart_grad) t.smart_grad += off;
123	    return t;
124	}
