126	// The L3-REAL ViT megakernel needs the FLOAT patch path + a grad-partial
127	// workspace. Kept a SEPARATE kernel + launcher (not folded into the surrogate
128	// fused_megakernel) so the surrogate path is untouched.
129	//
130	// Workspace layout (one flat float buffer the host allocates + the kernel owns):
131	//   [0 .. nCTA*total)              : per-CTA grad partials (cta-major)
132	//   [nCTA*total .. nCTA*total+nCTA): per-CTA loss partials (NLL sum per slice)
133	//   [.. +1)                        : the reduced scalar loss (loss/B) the host reads
134	// total == kVitTotalElems == 418017.
135	struct ViTInputCtx {
136	    const float* patches;  // [B, kNPatch, kPatch] fp32 image patches
137	    const int*   targets;  // [B]                  int32 target ids in [0,kVocab)
138	    int          B;        // batch size
139	    float*       workspace; // grad partials + loss partials + reduced loss
140	    float*       loss_out;  // device float the kernel writes the mean loss into
141	};
142	
143	// ── The persistent megakernel (L3-REAL). gridDim.x = #SMs (one CTA/SM), 256
144	//    threads/CTA. VitSampleSmem (~183.67 KB) lives in DYNAMIC smem (extern). ────
145	// sizes/offsets are NOT host-passed: per-tensor numel/offset live in the
146	// __constant__ tables kVitSizes/kVitOffsets (vit_layout.cuh), read directly by
147	// the reduce + optimizer phases.
148	template <OptId Opt>
149	__global__ void __launch_bounds__(SG_TUNED_MEGA_BLOCK)
150	fused_vit_megakernel(PersistentContext ctx,
151	                     float* __restrict__ params,
152	                     ViTInputCtx in,
153	                     float* __restrict__ grad,        // reduced grad [total]
154	                     float lr, int step, FusedOptState st) {
155	    extern __shared__ char vit_smem_raw[];
156	    VitSampleSmem& sm = *reinterpret_cast<VitSampleSmem*>(vit_smem_raw);
157	    GridBarrier bar = ctx.barrier();
158	    const int cta = blockIdx.x;
159	    const int nCTA = (int)ctx.n_ctas;
160	    const int64_t total = kVitTotalElems;
161	    float* my_partial = in.workspace + (int64_t)cta * total;   // this CTA's dW
162	    float* loss_part = in.workspace + (int64_t)nCTA * total;   // [nCTA]
163	
164	    // §3.4 register repartition (producer WG gives back, consumer WG claims).
165	    const int wg = threadIdx.x / 128;
166	    if (wg == 0) ::sg::sm90::wgs::warpgroup_reg_dealloc<32>();
167	    else         ::sg::sm90::wgs::warpgroup_reg_alloc<200>();
168	
169	    // ── P0: zero this CTA's grad-partial slice + its loss slot. ───────────────
170	    for (int64_t i = threadIdx.x; i < total; i += blockDim.x) my_partial[i] = 0.0f;
171	    if (threadIdx.x == 0) loss_part[cta] = 0.0f;
172	    bar.sync();   // B0
173	
174	    // ── P1: batch-parallel fwd+bwd. Fixed contiguous slice [b0,b1) for this CTA.
175	    VitWeights w = vit_bind(params);
176	    VitGrad g = vit_bind_grad(my_partial);
177	    const int B = in.B;
178	    const int base = B / nCTA, rem = B % nCTA;
179	    const int b0 = cta * base + (cta < rem ? cta : rem);
180	    const int cnt = base + (cta < rem ? 1 : 0);
181	    const int b1 = b0 + cnt;
182	    __shared__ int tgt_s;
183	    float nll_acc = 0.0f;              // fp32 slice accumulator (thread-0 holds it)
184	    const int patch_elems = vit::kNPatch * vit::kPatch;   // 16*49 = 784
185	    for (int b = b0; b < b1; ++b) {
186	        // Load this sample's float patches into smem (cooperative).
187	        const float* src = in.patches + (int64_t)b * patch_elems;
188	        for (int i = threadIdx.x; i < patch_elems; i += blockDim.x)
189	            sm.patch[i / vit::kPatch][i % vit::kPatch] = src[i];
190	        if (threadIdx.x == 0) tgt_s = in.targets[b];
191	        __syncthreads();
192	        float nll = vit_forward_sample(w, tgt_s, &sm);
193	        vit_backward_sample(w, g, tgt_s, B, &sm);
194	        if (threadIdx.x == 0) nll_acc += nll;   // fixed-order fp32 sum within slice
195	        __syncthreads();   // sample boundary: all grad writes done before reuse
196	    }
197	    if (threadIdx.x == 0) loss_part[cta] = nll_acc;
198	    bar.sync();   // B1: all CTA partials + loss slots complete
199	
200	    // ── P2: deterministic cross-CTA reduce. Work-steal the param ELEMENT-RANGES
201	    //    (one task = one parameter tensor; sum its elements across CTAs in
202	    //    ascending CTA index). Summation ORDER (ascending cta) is fixed →
203	    //    deterministic regardless of which CTA grabs the task. ─────────────────
204	    {
205	        __shared__ int task_slot;
206	        TaskQueue q = ctx.queue();
207	        for (int t = q.next_block(&task_slot); t < kVitNumTensors;
208	             t = q.next_block(&task_slot)) {
209	            const int n = kVitSizes[t];
210	            const int64_t off = (int64_t)kVitOffsets[t];
211	            for (int i = threadIdx.x; i < n; i += blockDim.x) {
212	                float acc = 0.0f;
213	                for (int c = 0; c < nCTA; ++c)
214	                    acc += in.workspace[(int64_t)c * total + off + i];
215	                grad[off + i] = acc;
216	            }
217	        }
218	    }
219	    // Loss reduction (fp64 ordered) by CTA 0 only — the loss rel-tol is the
220	    // tightest gate; fp32 atomic-summing many terms can miss it.
221	    if (cta == 0 && threadIdx.x == 0) {
222	        double s = 0.0;
223	        for (int c = 0; c < nCTA; ++c) s += (double)loss_part[c];
224	        float mean = (float)(s / (double)B);
225	        *in.loss_out = mean;
226	    }
227	    bar.sync_reset(ctx.g_next_task);   // B2: reduced grad ready; reset queue for P3
228	
229	    // ── P3: the REAL optimizer tail over the reduced grad (work-steal the 32
230	    //    tensors). apply_optimizer<Opt> is the canonical csrc/algorithms math. ──
231	    st.lr = lr;
232	    {
233	        __shared__ int task_slot;
234	        TaskQueue q = ctx.queue();
235	        for (int t = q.next_block(&task_slot); t < kVitNumTensors;
236	             t = q.next_block(&task_slot)) {
237	            const int n = kVitSizes[t];
238	            const int64_t off = (int64_t)kVitOffsets[t];
239	            const FusedOptState ts = vit_rebase_state<Opt>(st, off);
240	            float* __restrict__ p = params + off;
241	            const float* __restrict__ gg = grad + off;
242	            for (int i = threadIdx.x; i < n; i += blockDim.x)
243	                apply_optimizer<Opt>(p, gg, (int64_t)i, step, ts);
244	        }
245	    }
246	}
