248	// ── Host launcher — one persistent CTA per SM, 256 threads/CTA (2 warp-groups).
249	//    Mirrors launch_fused_decoder_megakernel's hang-freedom contract (occupancy≥1
250	//    or refuse), PLUS the DYNAMIC-SMEM opt-in that the ViT footprint requires:
251	//      (1) cudaFuncSetAttribute(MaxDynamicSharedMemorySize, sizeof(VitSampleSmem))
252	//      (2) dynamicSMemBytes = sizeof(VitSampleSmem) in the occ≥1 query
253	//      (3) dynamicSMemBytes = sizeof(VitSampleSmem) at <<<...>>>
254	//    All three are mandatory; missing any one makes the launch silently fail. ───
255	template <OptId Opt>
256	cudaError_t launch_fused_vit_megakernel(
257	        PersistentContext ctx, float* params, ViTInputCtx in,
258	        float* grad, float lr, int step, FusedOptState st, cudaStream_t stream) {
259	    int dev = 0;
260	    cudaError_t err = cudaGetDevice(&dev);
261	    if (err != cudaSuccess) return err;
262	    int n_sms = 0;
263	    err = cudaDeviceGetAttribute(&n_sms, cudaDevAttrMultiProcessorCount, dev);
264	    if (err != cudaSuccess) return err;
265	
266	    const int dyn_smem = (int)sizeof(VitSampleSmem);   // ≈ 188080 B (183.67 KB)
267	
268	    // (1) Opt in to >48 KB dynamic smem for THIS kernel. Without this the launch
269	    //     fails with cudaErrorInvalidValue (the static 48 KB default applies).
270	    err = cudaFuncSetAttribute(
271	        (const void*)&fused_vit_megakernel<Opt>,
272	        cudaFuncAttributeMaxDynamicSharedMemorySize, dyn_smem);
273	    if (err != cudaSuccess) return err;
274	
275	    // (2) Occupancy with the REAL dynamic-smem request (hang-freedom is honest).
276	    int occ = 0;
277	    err = cudaOccupancyMaxActiveBlocksPerMultiprocessor(
278	        &occ, (const void*)&fused_vit_megakernel<Opt>, SG_TUNED_MEGA_BLOCK,
279	        /*dynamicSMemBytes=*/dyn_smem);
280	    if (err != cudaSuccess) return err;
281	    // At least one CTA per SM must be resident or the grid barrier can never be
282	    // satisfied. ~183.67 KB dynamic smem fits the sm_90 227 KB cap at occ=1 (the
283	    // persistent megakernel is one-CTA-per-SM by design); if it cannot place one
284	    // block/SM, REFUSE rather than hang.
285	    assert(occ >= 1 &&
286	           "fused_vit_megakernel: 0 blocks/SM — GridBarrier would hang. The ViT "
287	           "per-sample smem (~184KB dynamic) + regs exceed one-block-per-SM "
288	           "occupancy on this device; reduce footprint or fall back to eager.");
289	    if (occ < 1) return cudaErrorLaunchOutOfResources;
290	
291	    const unsigned launch_ctas = (unsigned)n_sms;
292	    ctx.n_ctas = launch_ctas;
293	
294	    if (ctx.g_arrived) { err = cudaMemsetAsync(ctx.g_arrived, 0, sizeof(unsigned), stream); if (err) return err; }
295	    if (ctx.g_generation) { err = cudaMemsetAsync(ctx.g_generation, 0, sizeof(unsigned), stream); if (err) return err; }
296	    if (ctx.g_next_task) { err = cudaMemsetAsync(ctx.g_next_task, 0, sizeof(int), stream); if (err) return err; }
297	
298	    // (3) Launch WITH the dynamic-smem byte count.
299	    dim3 grid(launch_ctas), block(SG_TUNED_MEGA_BLOCK);
300	    fused_vit_megakernel<Opt><<<grid, block, dyn_smem, stream>>>(
301	        ctx, params, in, grad, lr, step, st);
302	    return cudaGetLastError();
303	}
