305	// ════════════════════════════════════════════════════════════════════════════
306	//  WGMMA CELL DRIVER (DESIGN-TC-PIPELINE.md Fork B, the ViT twin of the decoder
307	//  R2.3 driver). Compiled only under the wgmma token; the scalar path above is
308	//  untouched. The TC path's per-CTA tile scratch lives in HBM (NOT dynamic smem)
309	//  — the only smem the TC kernel needs is the tiny wgmma staging arena (one
310	//  A(64×16) + one B(N×16) bf16 tile + a 256-float reduction + the 10 dW specs),
311	//  which is STATIC (≈ 7 KB), so this kernel — unlike the scalar ViT one — needs
312	//  NO dynamic-smem opt-in. The big ViT activation footprint (which forced the
313	//  scalar path to 184 KB dynamic smem) becomes HBM acts here (Fork B), so the
314	//  occupancy story is the decoder TC one: static smem, 0 dynamic.
315	// ════════════════════════════════════════════════════════════════════════════
316	#if (SG_TUNED_GEMM_IMPL == SG_GEMM_IMPL_WGMMA)
317	
318	// TC megakernel threads: 256 (the engine's producer+consumer warpgroup layout;
319	// wgmma is warpgroup-scoped on threads 0..127). We do NOT apply the scalar
320	// path's asymmetric setmaxnreg (it would STARVE the MMA warpgroup); the
321	// validated selftest ran no split. We match it.
322	#define SG_VIT_TC_MEGA_BLOCK 256
323	
324	// ── smem arena for the unpipelined engine: one A(64×16) + one B(N×16) bf16 tile
325	//    + the 256-float reduction slot + the 10 dW specs (identical for all threads
326	//    → shared, not per-thread stack). 16B-aligned. N = SG_TUNED_TILE_N. ──
327	struct VitTcSmem {
328	    __nv_bfloat16 sA[64 * 16];
329	    __nv_bfloat16 sB[SG_TUNED_TILE_N * 16];
330	    float red[256];
331	    vittc::VitDwSpec spec[10];
332	};
333	
334	// ── TC workspace layout (carved from in.workspace; the host sizes it). Regions
335	//    (float units):
336	//      [0 .. acts_f)                      : VitActs bf16 region (reinterpreted)
337	//      [acts_f .. acts_f + nCTA*scratch)  : per-CTA tile scratch (f32)
338	//      [.. + nCTA*kLnVecElems)            : per-CTA LN-vec partials (f32)
339	//      [.. + nCTA)                        : per-CTA loss slots (f32)
340	//      [.. + 1)                           : reduced scalar loss (host reads it)
341	//    acts_f = ceil(acts_bf16 / 2). ──
342	__host__ __device__ __forceinline__ int64_t vit_tc_acts_floats(int T, int B) {
343	    return (vittc::vit_acts_bf16_count(T, B) + 1) / 2;
344	}
345	__host__ __device__ __forceinline__ int64_t vit_tc_workspace_floats(int T, int B, int nCTA) {
346	    return vit_tc_acts_floats(T, B)
347	         + (int64_t)nCTA * vittc::vit_tile_scratch_total_f32()
348	         + (int64_t)nCTA * vittc::kLnVecElems
349	         + nCTA + 1;
350	}
351	
352	#ifdef SG_VIT_PROFILE
353	// Diagnostic-only (behind SG_VIT_PROFILE; NEVER on the shipped path): per-phase
354	// clock64() deltas, max across CTAs (= critical-path duration per phase). Slots:
355	// [0]=P1 fwd, [1]=P1 bwd, [2]=B1 barrier wait, [3]=P2 dW-GEMM loop,
356	// [4]=P2 grad-assembly (biases+clspos+lnvec+loss), [5]=P3 opt tail. Read
357	// host-side via cudaMemcpyFromSymbol. clock64() is per-SM; a CTA stays on one SM
358	// so its own deltas are valid; atomicMax across CTAs gives the slowest CTA per
359	// phase.
360	__device__ unsigned long long g_vit_prof_max[6];
361	#endif
362	
363	template <OptId Opt>
364	__global__ void __launch_bounds__(SG_VIT_TC_MEGA_BLOCK)
365	fused_vit_megakernel_tc(PersistentContext ctx,
366	                        float* __restrict__ params,
367	                        ViTInputCtx in,
368	                        float* __restrict__ grad,
369	                        float lr, int step, FusedOptState st) {
370	    __shared__ VitTcSmem sm;
371	    GridBarrier bar = ctx.barrier();
372	    const int cta = blockIdx.x;
373	    const int nCTA = (int)ctx.n_ctas;
374	    const int B = in.B;
375	    const int T = B * vit::kSeq;
376	    const int Tp = B * vit::kNPatch;
377	
378	    // Workspace partition.
379	    float* ws = in.workspace;
380	    const int64_t acts_f = vit_tc_acts_floats(T, B);
381	    __nv_bfloat16* acts_base = reinterpret_cast<__nv_bfloat16*>(ws);
382	    float* scratch_base = ws + acts_f;
383	    const int64_t scratch_per = vittc::vit_tile_scratch_total_f32();
384	    float* lnvec_base = scratch_base + (int64_t)nCTA * scratch_per;
385	    float* loss_part  = lnvec_base + (int64_t)nCTA * vittc::kLnVecElems;
386	    float* loss_out   = loss_part + nCTA;
387	
388	    vittc::VitActs acts = vittc::vit_acts_bind(acts_base, T, B);
389	    vittc::VitTileScratch sc = vittc::vit_tile_scratch_bind(scratch_base + (int64_t)cta * scratch_per);
390	    float* my_lnvec = lnvec_base + (int64_t)cta * vittc::kLnVecElems;
391	
392	    VitWeights w = vit_bind(params);
393	
394	    // ── P0: zero this CTA's LN-vec partials + loss slot (dW/cls/pos/patch grads
395	    //    are written-once → no pre-zero). ──
396	    for (int i = threadIdx.x; i < vittc::kLnVecElems; i += blockDim.x) my_lnvec[i] = 0.0f;
397	    if (threadIdx.x == 0) loss_part[cta] = 0.0f;
398	    bar.sync();   // B0
399	
400	    // ── P1: token-tile-parallel fwd+bwd. Each CTA grid-strides over tiles of
401	    //    kTileM rows; for its tile it runs fwd (→ acts X, NLL) then bwd (→ acts
402	    //    dY, dh0, LN-vec partials). Barrier-free within the tile. ──
403	    const int nrows_tile = vittc::kTileM;
404	    const int n_tiles = (T + nrows_tile - 1) / nrows_tile;
405	    float nll_acc = 0.0f;
406	#ifdef SG_VIT_PROFILE
407	    unsigned long long prof_fwd = 0, prof_bwd = 0;
408	#endif
409	    for (int ti = cta; ti < n_tiles; ti += nCTA) {
410	        const int g0 = ti * nrows_tile;
411	        const int nrows = (T - g0) < nrows_tile ? (T - g0) : nrows_tile;
412	#ifdef SG_VIT_PROFILE
413	        __syncthreads(); unsigned long long _c0 = clock64();
414	#endif
415	        float nll = vittc::vittc_forward_tile(w, g0, nrows, acts, sc, in.patches, in.targets,
416	                                              sm.sA, sm.sB, sm.red);
417	#ifdef SG_VIT_PROFILE
418	        __syncthreads(); unsigned long long _c1 = clock64();
419	#endif
420	        vittc::vittc_backward_tile(w, g0, nrows, B, acts, sc, in.targets,
421	                                   my_lnvec, sc.work2, sm.sA, sm.sB, sm.red);
422	#ifdef SG_VIT_PROFILE
423	        __syncthreads(); unsigned long long _c2 = clock64();
424	        if (threadIdx.x == 0) { prof_fwd += _c1 - _c0; prof_bwd += _c2 - _c1; }
425	#endif
426	        if (threadIdx.x == 0) nll_acc += nll;
427	        __syncthreads();
428	    }
429	    if (threadIdx.x == 0) loss_part[cta] = nll_acc;
430	#ifdef SG_VIT_PROFILE
431	    if (threadIdx.x == 0) {
432	        atomicMax(&g_vit_prof_max[0], prof_fwd);
433	        atomicMax(&g_vit_prof_max[1], prof_bwd);
434	    }
435	    unsigned long long _b1a = (threadIdx.x == 0) ? clock64() : 0;
436	#endif
437	    bar.sync();   // B1: all acts (X + dY) + LN-vec partials complete
438	#ifdef SG_VIT_PROFILE
439	    if (threadIdx.x == 0) { unsigned long long _b1b = clock64(); atomicMax(&g_vit_prof_max[2], _b1b - _b1a); }
440	#endif
441	
442	    // ── P2: assemble all 32 grads into `grad`. dW output-stationary (gt % nCTA),
443	    //    biases, cls/pos owner-scan, LN-vec reduce. No partials. The 10 dW specs
444	    //    are built into SHARED smem (thread 0; identical for all). ──
445	    if (threadIdx.x == 0) vittc::vittc_build_dw_specs(acts, B, T, Tp, sm.spec);
446	    __syncthreads();
447	    vittc::VitDwSpec* spec = sm.spec;
448	    const int n_dw = vittc::vittc_dw_total_tiles<SG_TUNED_TILE_N>(spec);
449	#ifdef SG_VIT_PROFILE
450	    __syncthreads(); unsigned long long _dwa = (threadIdx.x == 0) ? clock64() : 0;
451	#endif
452	    for (int gt = cta; gt < n_dw; gt += nCTA)
453	        vittc::vittc_dw_run_tile<SG_TUNED_TILE_N>(spec, gt, acts.dh0, grad, sm.sA, sm.sB);
454	#ifdef SG_VIT_PROFILE
455	    __syncthreads();
456	    if (threadIdx.x == 0) { unsigned long long _dwb = clock64(); atomicMax(&g_vit_prof_max[3], _dwb - _dwa); }
457	    unsigned long long _gaa = (threadIdx.x == 0) ? clock64() : 0;
458	#endif
459	    vittc::vittc_dw_biases(spec, acts.dh0, grad, cta, nCTA);
460	    vittc::vittc_clspos_owner_scan(acts, T, grad, cta, nCTA);
461	    vittc::vittc_lnvec_reduce(lnvec_base, grad, nCTA, cta);
462	    // Loss reduce (fp64) by CTA 0.
463	    if (cta == 0 && threadIdx.x == 0) {
464	        double s = 0.0;
465	        for (int c = 0; c < nCTA; ++c) s += (double)loss_part[c];
466	        *in.loss_out = (float)(s / (double)B);
467	    }
468	    (void)loss_out;
469	#ifdef SG_VIT_PROFILE
470	    if (threadIdx.x == 0) { unsigned long long _gab = clock64(); atomicMax(&g_vit_prof_max[4], _gab - _gaa); }
471	#endif
472	    bar.sync_reset(ctx.g_next_task);   // B2: reduced grad ready; reset queue
473	
474	    // ── P3: scalar optimizer tail over the reduced grad (REUSED verbatim). ──
475	    st.lr = lr;
476	#ifdef SG_VIT_PROFILE
477	    unsigned long long _p3a = (threadIdx.x == 0) ? clock64() : 0;
478	#endif
479	    {
480	        __shared__ int task_slot;
481	        TaskQueue q = ctx.queue();
482	        for (int t = q.next_block(&task_slot); t < kVitNumTensors;
483	             t = q.next_block(&task_slot)) {
