1055	// Total number of 64×N dW output tiles across the 10 weights (for the tile loop).
1056	// The N-tiling is over Kin (the in-dim), padded so the GEMM N covers it.
1057	template <int N>
1058	__device__ __forceinline__ int vittc_dw_total_tiles(const VitDwSpec spec[10]) {
1059	    int n = 0;
1060	    for (int s = 0; s < 10; ++s)
1061	        n += ((spec[s].Nout + 63) / 64) * ((spec[s].Kin + N - 1) / N);
1062	    return n;
1063	}
