1065	// Run ONE global dW tile `gt` (if it belongs to this CTA). MaxAtomsM=1 (one 64×N
1066	// tile). For patch_proj (kind==1) the dY adjoint is dh0's PATCH rows: dh0 is
1067	// [T,d] token-row-major; its patch rows for sample si, patch p are at token row
1068	// si*kSeq + (1+p). The dW contracts over the Tp patch rows in ascending patch
1069	// order (k=0..Tp-1 maps to si=k/kNPatch, p=k%kNPatch → token row si*kSeq+1+p).
1070	template <int N>
1071	__device__ __forceinline__ void vittc_dw_run_tile(
1072	        const VitDwSpec spec[10], int gt, const __nv_bfloat16* __restrict__ dh0,
1073	        float* __restrict__ grad, __nv_bfloat16* sA, __nv_bfloat16* sB) {
1074	    int acc = 0, s = 0, m_atom = 0, n_tile = 0;
1075	    for (s = 0; s < 10; ++s) {
1076	        const int ma = (spec[s].Nout + 63) / 64;
1077	        const int nt = (spec[s].Kin + N - 1) / N;
1078	        if (gt < acc + ma * nt) { int loc = gt - acc; m_atom = loc / nt; n_tile = loc % nt; break; }
1079	        acc += ma * nt;
1080	    }
1081	    const VitDwSpec& sp = spec[s];
1082	    const int mbase = m_atom * 64;
1083	    const int n0 = n_tile * N;
1084	    const int n_real = (sp.Kin - n0) < N ? (sp.Kin - n0) : N;
1085	    const int Nout = sp.Nout, Kin = sp.Kin;
1086	    const __nv_bfloat16* dY = sp.dY; const __nv_bfloat16* X = sp.X;
1087	    if (sp.kind == 1) {
1088	        // patch_proj: K = Tp patch rows (ascending), padded UP to a multiple of 16.
1089	        const int Tp = sp.K;
1090	        const int Kpad = ((Tp + wgs::kWgmmaAtomK - 1) / wgs::kWgmmaAtomK) * wgs::kWgmmaAtomK;
1091	        const int k_steps = Kpad / wgs::kWgmmaAtomK;
1092	        // A[m=out, k=patchrow] = dh0[token row of patchrow, out]  (transposed read).
1093	        auto srcA = [&] (int m, int k) -> __nv_bfloat16 {
1094	            if (m >= Nout || k >= Tp) return __float2bfloat16(0.f);
1095	            const int si = k / vit::kNPatch, p = k % vit::kNPatch;
1096	            const int trow = si * vit::kSeq + (1 + p);
1097	            return dh0[(int64_t)trow * vit::kD + m]; };
1098	        // B[n=in, k=patchrow] = X_patch[patchrow, in].
1099	        auto srcB = [&] (int n, int k) -> __nv_bfloat16 {
1100	            int nn = n0 + n; if (nn >= Kin || k >= Tp) return __float2bfloat16(0.f);
1101	            return X[(int64_t)k * Kin + nn]; };
1102	        auto out  = [&] (int m, int n, float v) {
1103	            if (m < Nout) grad[sp.grad_off + (int64_t)m * Kin + n0 + n] = v; };
1104	        tc_gemm_block_unpipelined<N, /*MaxAtomsM=*/1>(
1105	            mbase, /*m_atoms=*/1, n_real, k_steps, srcA, srcB, out, sA, sB);
1106	        return;
1107	    }
1108	    const int k_steps = sp.K / wgs::kWgmmaAtomK;     // K = T or B (must be /16; padded by caller)
1109	    // A[m=out, k=t] = dY[t,out]  (transposed read); B[n=in, k=t] = X[t,in] (transposed).
1110	    auto srcA = [&] (int m, int k) -> __nv_bfloat16 {
1111	        return m < Nout ? dY[(int64_t)k * Nout + m] : __float2bfloat16(0.f); };
1112	    auto srcB = [&] (int n, int k) -> __nv_bfloat16 {
1113	        int nn = n0 + n; return nn < Kin ? X[(int64_t)k * Kin + nn] : __float2bfloat16(0.f); };
1114	    auto out  = [&] (int m, int n, float v) {
1115	        if (m < Nout) grad[sp.grad_off + (int64_t)m * Kin + n0 + n] = v; };
1116	    tc_gemm_block_unpipelined<N, /*MaxAtomsM=*/1>(
1117	        mbase, /*m_atoms=*/1, n_real, k_steps, srcA, srcB, out, sA, sB);
1118	}
