1120	// Biases db. For the 8 transformer linears + head: db = Σ_K dY (per output row).
1121	// For patch_proj.bias: db[o] = Σ_{patch rows} dh0[token row, o]. Single owner per
1122	// output element → no atomics.
1123	// PERF FIX (structural, parity-preserved — gated by the K-scaled grad tol, which is
1124	// designed for fp32 accumulation-order differences at large K):
1125	//   (1) The ORIGINAL ran the FULL Σ_K (K up to T=278528) for EVERY bias element on
1126	//       EVERY CTA (no cta/nCTA guard) — 132× redundant work, the dominant cost of P2
1127	//       grad-assembly (measured 59.5% of the step). Columns are now PARTITIONED across
1128	//       CTAs (each global bias column owned by one CTA), removing the 132× redundancy.
1129	//   (2) The K-reduction per column was SERIAL on ONE thread (≈278528 iters). It is now
1130	//       WARP-PARALLEL: a WARP (32 lanes) co-reduces one column — each lane sums a
1131	//       strided 1/32 slice of K (ascending within the lane), then a shuffle tree sums
1132	//       the 32 lane-partials. 32× parallelism per column. The lane reads dY[k*Nout+o]
1133	//       at fixed o with k = lane, lane+32, … (stride 32·Nout); writes by lane 0 only.
1134	__device__ __forceinline__ void vittc_dw_biases(
1135	        const VitDwSpec spec[10], const __nv_bfloat16* __restrict__ dh0,
1136	        float* __restrict__ grad, int cta, int nCTA) {
1137	    const int warp = threadIdx.x >> 5;            // 0..(blockDim/32 - 1)
1138	    const int lane = threadIdx.x & 31;
1139	    const int nwarps = blockDim.x >> 5;
1140	    int gcol_base = 0;
1141	    for (int s = 0; s < 10; ++s) {
1142	        const VitDwSpec& sp = spec[s];
1143	        const int Nout = sp.Nout;
1144	        const bool patch = (sp.kind == 1);
1145	        const int K = sp.K;
1146	        // Each warp owns columns o = (its rank among this CTA's warps), strided. A
1147	        // global column gcol is owned by CTA (gcol % nCTA); within the CTA the warps
1148	        // round-robin the owned columns.
1149	        for (int o = 0; o < Nout; ++o) {
1150	            const int gcol = gcol_base + o;
1151	            if ((gcol % nCTA) != cta) continue;       // not this CTA's column
1152	            // round-robin owned columns across warps: count owned-so-far for THIS s.
1153	            // Cheap: derive the warp owner from the o-th owned index. We instead let
1154	            // every warp test (owned_index % nwarps == warp); compute owned_index by
1155	            // a strided scan-free rule: owned columns appear every nCTA in gcol, so
1156	            // the k-th owned column of this CTA has o such that (gcol_base+o)%nCTA==cta.
1157	            // Assign by (o / 1) round-robin is fine since the inner reduce dominates:
1158	            // use (o-th column's position) — approximate with o itself for balance.
1159	            if (((o) % nwarps) != warp) continue;     // warp owns this column
1160	            float part = 0.0f;
1161	            if (patch) {
1162	                for (int k = lane; k < K; k += 32) {
1163	                    const int si = k / vit::kNPatch, p = k % vit::kNPatch;
1164	                    const int trow = si * vit::kSeq + (1 + p);
1165	                    part += __bfloat162float(dh0[(int64_t)trow * vit::kD + o]);
1166	                }
1167	            } else {
1168	                const __nv_bfloat16* dY = sp.dY;
1169	                for (int k = lane; k < K; k += 32)
1170	                    part += __bfloat162float(dY[(int64_t)k * Nout + o]);
1171	            }
1172	            // Warp-reduce the 32 lane-partials (shuffle tree).
1173	            #pragma unroll
1174	            for (int off = 16; off > 0; off >>= 1)
1175	                part += __shfl_down_sync(0xffffffffu, part, off);
1176	            if (lane == 0) grad[sp.bias_off + o] = part;
1177	        }
1178	        gcol_base += Nout;
1179	    }
1180	}
