1183	//  P2 — CLS + POS owner-scan. dh0 [T,d] (bf16) holds grad wrt h0 (post-cat,
1184	//    pre-pos). cls_token grad = Σ_samp dh0[CLS row (pos 0)]; pos.weight[p] grad
1185	//    = Σ_t dh0[t] over t with (t%kSeq)==p (ALL 17 positions). Fixed t-order +
1186	//    single owner per element → deterministic, atomic-free. The owner of a
1187	//    feature j is round-robin (j % ... is implicit via thread stride; only ONE
1188	//    CTA — cta 0 — writes these tiny ([d] and [17×d]) tensors to avoid a
1189	//    cross-CTA race, since they are not tiled by gt). Mirrors the decoder
1190	//    embed owner-scan, ViT variant.
1191	// ════════════════════════════════════════════════════════════════════════
1192	__device__ __forceinline__ void vittc_clspos_owner_scan(
1193	        const VitActs& acts, int T, float* __restrict__ grad, int cta, int nCTA) {
1194	    const int cls_off = kVitOffsets[0];   // cls_token [1,1,d] → [d]
1195	    const int pos_off = kVitOffsets[3];   // pos.weight [kSeq, d]
1196	    const int nsamp = T / vit::kSeq;
1197	    // cls_token: owned by cta 0 (tiny [d]); each thread owns feature j.
1198	    if (cta == 0) {
1199	        for (int j = threadIdx.x; j < vit::kD; j += blockDim.x) {
1200	            float accv = 0.0f;
1201	            for (int si = 0; si < nsamp; ++si)
1202	                accv += __bfloat162float(acts.dh0[(int64_t)(si * vit::kSeq) * vit::kD + j]);
1203	            grad[cls_off + j] = accv;
1204	        }
1205	    }
1206	    // pos rows: round-robin by position p across CTAs (p in [0,kSeq)).
1207	    // PERF FIX: the ORIGINAL looped ALL T tokens with `if (t%kSeq)==p`, doing 17×
1208	    // (kSeq) the necessary reads (keeping only 1/17). Token rows with t%kSeq==p are
1209	    // exactly t = p, p+kSeq, p+2·kSeq, … so stride DIRECTLY by kSeq (the same
1210	    // ascending-t order → bit-identical fp32 sum). 17× fewer reads.
1211	    for (int p = cta; p < vit::kSeq; p += nCTA) {
1212	        for (int j = threadIdx.x; j < vit::kD; j += blockDim.x) {
1213	            float accv = 0.0f;
1214	            for (int t = p; t < T; t += vit::kSeq)
1215	                accv += __bfloat162float(acts.dh0[(int64_t)t * vit::kD + j]);
1216	            grad[pos_off + (int64_t)p * vit::kD + j] = accv;
1217	        }
1218	    }
1219	}
