1221	// ════════════════════════════════════════════════════════════════════════
1222	//  P2 — LN-vector grad reduce. The 10 γ/β grads were accumulated tile-locally
1223	//    into each CTA's lnvec partials [kNumLnVec × d]; sum across CTAs in
1224	//    ASCENDING CTA index (deterministic) into the 10 vit_layout slots of grad.
1225	//    `lnvec_base` is the start of the [nCTA × kLnVecElems] partial region.
1226	// ════════════════════════════════════════════════════════════════════════
1227	__device__ __forceinline__ void vittc_lnvec_reduce(
1228	        const float* __restrict__ lnvec_base, float* __restrict__ grad,
1229	        int nCTA, int cta) {
1230	    for (int v = cta; v < kNumLnVec; v += nCTA) {
1231	        const int goff = kLnVecTensorIdx[v];
1232	        const int64_t gbase = kVitOffsets[goff];
1233	        for (int j = threadIdx.x; j < vit::kD; j += blockDim.x) {
1234	            float accv = 0.0f;
1235	            for (int c = 0; c < nCTA; ++c)
1236	                accv += lnvec_base[(int64_t)c * kLnVecElems + (int64_t)v * vit::kD + j];
1237	            grad[gbase + j] = accv;
1238	        }
1239	    }
1240	}
