inline void clip_grad_norms_device_side(
    std::vector<torch::Tensor>& grads,
    size_t n_params,
    float grad_clip_norm
) {
    if (grad_clip_norm <= 0.0f) return;

    // Collect the present grads once. Fused multi-tensor ops want a flat list.
    std::vector<torch::Tensor> present;
    present.reserve(n_params);
    for (size_t i = 0; i < n_params; i++) {
        if (grads[i].defined() && grads[i].numel() > 0)
            present.push_back(grads[i]);
    }
    if (present.empty()) return;

    // Per-tensor L2 norms via a single fused multi-tensor reduction
    // (torch::_foreach_norm), replacing the per-tensor upcast + dot + add_
    // (≈2N kernel launches) with one foreach launch. Numerics: the L2 norm of
    // each tensor is accumulated into a fp32 sum-of-squares (squaring the
    // per-tensor norm == that tensor's sum-of-squares), matching the original
    // fp32 accumulation of the global sum-of-squares. To preserve the original
    // precision when grads are NOT already fp32, upcast those (only) to fp32
    // before the norm; fp32 grads skip the upcast entirely.
    bool all_fp32 = true;
    for (auto& g : present)
        if (g.scalar_type() != torch::kFloat32) { all_fp32 = false; break; }

    std::vector<torch::Tensor> norm_inputs;
    if (all_fp32) {
        norm_inputs = present;
    } else {
        norm_inputs.reserve(present.size());
        for (auto& g : present)
            norm_inputs.push_back(g.scalar_type() == torch::kFloat32
                                      ? g
                                      : g.to(torch::kFloat32));
    }

    auto norms = torch::_foreach_norm(norm_inputs, /*p=*/2);

258	    auto stacked = torch::stack(norms).to(torch::kFloat32);
259	    float total_norm =
260	        std::sqrt(stacked.dot(stacked).item<float>());
261	
262	    if (total_norm > grad_clip_norm) {
263	        float clip_coef = grad_clip_norm / (total_norm + 1e-6f);
264	        // Fused multi-tensor in-place scale of the present grads.
265	        torch::_foreach_mul_(present, clip_coef);
266	    }
267	}
268	
269	// ── Device-side SAM grad-norm: single CPU sync instead of N ──────────
270	inline float compute_sam_grad_norm_device_side(
271	    std::vector<torch::Tensor>& grads,
272	    size_t n_grads
273	) {
274	    torch::Device dev(torch::kCPU);
275	    for (size_t i = 0; i < n_grads; i++) {
276	        if (grads[i].defined() && grads[i].numel() > 0) {
277	            dev = grads[i].device();
278	            break;
279	        }
280	    }
281	    auto norm_sq = torch::zeros(
282	        {1}, torch::TensorOptions().device(dev).dtype(torch::kFloat32));
283	    for (size_t i = 0; i < n_grads; i++) {
284	        if (grads[i].defined() && grads[i].numel() > 0) {
285	            auto g_flat = grads[i].to(torch::kFloat32).reshape(-1);
286	            norm_sq.add_(g_flat.dot(g_flat));
287	        }
288	    }
289	    return std::sqrt(norm_sq.item<float>()) + 1e-12f;
290	}
